import{_ as a,C as i,o as s,c,aj as r,E as d,j as e,a as n}from"./framework.js";const T=JSON.parse('{"title":"Authentication | Development | Admin CMS","description":"Configure access control rules for front-end site requests: match requests by URL / HTTP method, then run JWT validation or custom KScript. On failure, return an HTTP status code or…","frontmatter":{"title":"Authentication | Development | Admin CMS","description":"Configure access control rules for front-end site requests: match requests by URL / HTTP method, then run JWT validation or custom KScript. On failure, return an HTTP status code or…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/development/authentication.html"}]]},"headers":[],"relativePath":"cms/development/authentication.md","filePath":"en/cms/development/authentication.md","lastUpdated":1781010536000}'),l={name:"cms/development/authentication.md"};function u(h,t,g,p,m,b){const o=i("DocImage");return s(),c("div",null,[t[0]||(t[0]=r('<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><blockquote><p>Menu: <strong>Development → Authentication</strong><br> Deep link: <code>/_Admin/development/authentication?SiteId={siteGuid}</code></p></blockquote><p>Configure <strong>access control rules</strong> for front-end site requests: match requests by URL / HTTP method, then run <strong>JWT validation</strong> or <strong>custom KScript</strong>. On failure, return an HTTP status code or redirect. Rules run before rendering for requests that hit bound site routes (pages, APIs, etc.).</p><div class="tip custom-block"><p class="custom-block-title">Permissions</p><p>Menu permission: <code>authentication</code> (view). <strong>Create</strong>, edit rules require <code>authentication·edit</code>; multi-select <strong>Delete</strong> requires <code>authentication·delete</code>.</p></div><div class="info custom-block"><p class="custom-block-title">Difference from site account login</p><p>This page controls <strong>whether visitor requests are allowed to continue rendering</strong> (gateway-style rules). It is not Kooboo admin account login, nor the site account login flow in <a href="/kb-docs/api/getting-started/auth.html">k.account</a>. JWT validation uses <a href="/kb-docs/api/security/">k.security.jwt</a> to decode tokens in the request.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#edit-menu">Edit Menu</a>, enable <strong>Development → Authentication</strong>.</li><li>Open <strong>Development → Authentication</strong> in the left sidebar.</li></ol>',7)),d(o,{src:"/cms/development/authentication-overview.png",alt:"Authentication list overview",width:"1120"}),t[1]||(t[1]=r('<h2 id="rule-list" tabindex="-1">Rule List <a class="header-anchor" href="#rule-list" aria-label="Permalink to &quot;Rule List&quot;">​</a></h2><h3 id="toolbar" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Button</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><strong>Create</strong></td><td><code>authentication·edit</code></td><td>Open <a href="#create-and-edit-rule-dialog">create/edit rule dialog</a></td></tr></tbody></table>',3)),d(o,{src:"/cms/development/authentication-toolbar.png",alt:"Authentication toolbar",width:"1120"}),t[2]||(t[2]=r('<h3 id="list-table" tabindex="-1">List table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Unique rule identifier (name cannot be changed in the list after creation; configure only in the edit dialog)</td></tr><tr><td><strong>Matcher</strong></td><td><code>None</code> / <code>Any</code> / <code>Condition</code>; when <code>Condition</code>, shows a condition summary (e.g. <code>url = &#39;/api&#39;</code>)</td></tr><tr><td><strong>Action</strong></td><td><code>None</code> / <code>JwtAuth</code> / <code>CustomCode</code></td></tr><tr><td><strong>Failed action</strong></td><td><code>None</code> / <code>ResultCode</code> / <code>Redirect</code>; when action is <code>CustomCode</code>, column shows <code>CustomCode</code></td></tr><tr><td><strong>Parameters</strong></td><td>Failure-related parameters: custom code name, <code>httpCode</code>, redirect <code>url</code>, etc.</td></tr><tr><td><strong>Last modified</strong></td><td>Save time</td></tr><tr><td><strong>Actions</strong></td><td><strong>Settings</strong> icon opens <a href="#create-and-edit-rule-dialog">edit</a></td></tr></tbody></table><p>Supports multi-select <strong>Delete</strong> (<code>authentication·delete</code>).</p>',3)),d(o,{src:"/cms/development/authentication-list-table.png",alt:"Authentication list",width:"1120"}),t[3]||(t[3]=e("h2",{id:"create-and-edit-rule-dialog",tabindex:"-1"},[n("Create and Edit Rule Dialog "),e("a",{class:"header-anchor",href:"#create-and-edit-rule-dialog","aria-label":'Permalink to "Create and Edit Rule Dialog"'},"​")],-1)),t[4]||(t[4]=e("p",null,[n("Opened by "),e("strong",null,"Create"),n(" or row "),e("strong",null,"Settings"),n(". For new rules, fill in "),e("strong",null,"Name"),n(" (1–50 characters, letter or digit first, unique); name cannot be changed when editing an existing rule.")],-1)),d(o,{src:"/cms/development/authentication-edit-dialog.png",alt:"Authentication rule edit dialog",width:"1120"}),t[5]||(t[5]=r('<h3 id="matcher" tabindex="-1">Matcher <a class="header-anchor" href="#matcher" aria-label="Permalink to &quot;Matcher&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><strong>None</strong></td><td>Does not participate in matching (typically a placeholder; will not match requests)</td></tr><tr><td><strong>Any</strong></td><td>Matches all requests entering the rule chain</td></tr><tr><td><strong>Condition</strong></td><td>Match by conditions below; multiple conditions are <strong>AND (&amp;&amp;)</strong> — all must be satisfied</td></tr></tbody></table><p>When <strong>Condition</strong>, each row includes:</p><table tabindex="0"><thead><tr><th>Field</th><th>Options</th><th>Description</th></tr></thead><tbody><tr><td>Left</td><td><code>url</code>, <code>method</code></td><td>Request relative path and HTTP method respectively</td></tr><tr><td>Operator</td><td><code>=</code>, <code>!=</code>, <code>contains</code>, <code>notcontains</code>, <code>startwith</code>, <code>notstartwith</code></td><td>Comparisons are case-insensitive</td></tr><tr><td>Right</td><td>Text</td><td>Value compared against the left field</td></tr></tbody></table><p>You can <strong>add</strong> / <strong>delete</strong> condition rows; at least one valid condition is required to save.</p>',5)),d(o,{src:"/cms/development/authentication-condition.png",alt:"Condition matcher and condition rows",width:"1120"}),t[6]||(t[6]=r('<h3 id="action" tabindex="-1">Action <a class="header-anchor" href="#action" aria-label="Permalink to &quot;Action&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><strong>None</strong></td><td>Allow after match, no validation</td></tr><tr><td><strong>JwtAuth</strong></td><td>Validate with JWT decode; on failure, run <strong>Failed action</strong> below</td></tr><tr><td><strong>CustomCode</strong></td><td>Run inline <strong>TypeScript/KScript</strong> (Monaco editor); on failure, script sets response status</td></tr></tbody></table><p>When <strong>CustomCode</strong> is selected, a code editor appears with a default example: check the <code>Authorization</code> header and call <code>k.response.unauthorized()</code>. Saves inline <code>customCode</code> body (may also be associated with site <strong>Code</strong> resources; list load may backfill body from <code>customCodeName</code>).</p><p>When <strong>JwtAuth</strong> is selected, the <strong>Failed action</strong> section appears (see below).</p><h3 id="failed-action" tabindex="-1">Failed action <a class="header-anchor" href="#failed-action" aria-label="Permalink to &quot;Failed action&quot;">​</a></h3><p>Shown only when <strong>Action</strong> is <strong>JwtAuth</strong> (<code>CustomCode</code> handles the response in script).</p><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><strong>None</strong></td><td>On JWT validation failure, write <code>value</code> from decode result to response body</td></tr><tr><td><strong>ResultCode</strong></td><td>Return specified <strong>HTTP status code</strong> (e.g. <code>401</code>)</td></tr><tr><td><strong>Redirect</strong></td><td><strong>302</strong> redirect to the <strong>URL</strong> entered; automatically appends <code>returnurl</code> query parameter (current request path)</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Extra field</th><th>When shown</th><th>Description</th></tr></thead><tbody><tr><td><strong>HTTP status code</strong></td><td><code>ResultCode</code></td><td>Required, valid HTTP status code</td></tr><tr><td><strong>URL</strong></td><td><code>Redirect</code></td><td>Required, redirect target (spaces stripped on input)</td></tr></tbody></table><h2 id="how-rules-take-effect" tabindex="-1">How Rules Take Effect <a class="header-anchor" href="#how-rules-take-effect" aria-label="Permalink to &quot;How Rules Take Effect&quot;">​</a></h2><ul><li>Applies only to requests on <strong>bound site routes</strong> (pages, APIs, etc. with <code>Route.objectId</code>); pure static or unmatched routes do not go through this list.</li><li>The system tries rules in <strong>list order</strong>; the <strong>first</strong> matching rule runs and later rules are skipped. With multiple rules, put more specific <code>Condition</code> rules first, or avoid overlapping <code>Any</code>.</li><li><code>JwtAuth</code>: on successful decode with <code>code !== 1</code>, allow and put <code>value</code> in request context <code>jwt_payload</code>; <code>code === 1</code> is failure, handled per <strong>Failed action</strong>.</li><li><code>CustomCode</code>: after script runs, allow if response status <strong>&lt; 300</strong>, otherwise request stops (middleware may return <strong>403</strong>).</li><li>When validation fails and no complete response is written, <strong>403</strong> may be returned.</li></ul><p>Common APIs in custom code: <a href="/kb-docs/api/request/">k.request</a>, <a href="/kb-docs/api/response/">k.response</a> (e.g. <code>unauthorized()</code>), <a href="/kb-docs/api/security/">k.security.jwt</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./">Development overview</a></td><td>Development group index</td></tr><tr><td><a href="./code.html">Code</a></td><td>CodeBlock, usable with CustomCode</td></tr><tr><td><a href="/kb-docs/api/security/">k.security.jwt</a></td><td>JWT encode/decode</td></tr><tr><td><a href="/kb-docs/api/response/">k.response</a></td><td><code>unauthorized()</code>, redirect, etc.</td></tr><tr><td><a href="/kb-docs/api/getting-started/auth.html">Authentication and authorization (API)</a></td><td><code>k.account</code> member login (not this page&#39;s rules)</td></tr></tbody></table>',13))])}const w=a(l,[["render",u]]);export{T as __pageData,w as default};
